%[text] %[text:anchor:T_360F0929] # EEG Artifacts
%[text] This script investigates how tACS stimulation artifacts affect EEG/LFP analysis and shows results for FASTR, FBAR, and RBAR algorithms.
%[text:tableOfContents]{"heading":"Table of Contents"}
%%
%[text] %[text:anchor:H_D32E8D0B] ## Setup Simulation
%[text] First define the stimulation and recording parameters.
run('../startup.m'); % Make sure all toolboxes are on the path
defaults = [];
defaults.reproducible              = true;    % Fix the random number generator to get reproducible results
%[text] Stimulation Equipment:
defaults.stimulatorSamplingRate    = 1e3;     % 1 kHz 
defaults.currentResolution         = 1e-6;    % 1 muA

%[text] Recording equipment (assuming essentially a linear amplifier for the signals simulated here).
defaults.recordingSamplingRate     = 5e3;     % 5kHz
defaults.amplifierLinearRange      = 200e-3;  % [V] Range over which the amplifier is linear
defaults.adcNonlinearity           = 100;     % linear inside the range,saturation outside
defaults.adcRange                  = 200e-3;  % The range of the ADC; bits are distributed evenly across this +/- range.
defaults.adcBitDepth               = 24;      % Number of bits in the ADC
defaults.amplifierGain              = 1;      % Preamplifier gain


defaults.highPass                  = 0.01;    % Analog filter of the recording amplifier
defaults.digitalLowPass            = 100;     % Low pass filter after digitization
%[text] Experiment:
defaults.duration                  = 2*60;   % 2 min of data
defaults.tacsAmplitude             = 1e-3;   % 1 mA 
defaults.resistance                = 15;     % 15 Ohm: 1 mA - > 15 mV artifact
defaults.tacsFrequency             = 10;     % 10 Hz
%[text] Neural Signals: background noise plus an oscillation near 24 Hz.
defaults.additive                  = 100e-6;   % Background Noise stdev
defaults.lfpFrequency              = 24;       % Simulated oscillation peak frequency
defaults.lfpAmplitude              = 10e-6;    % Oscillation peak amplitude
defaults.lfpPeakWidth              = 1;        % Oscillation bandwidth.
%[text] And setup the base parameters for artifiact removal
ar = [];
ar.recordingSamplingRate = defaults.recordingSamplingRate; % Match to the recording
ar.segmentDuration       = 3;
ar.tacsFrequency         = defaults.tacsFrequency;
arArgs = namedargs2cell(ar); % For easy reuse below.
%[text] Setup the parameters for three artifact removal algorithms to explore.

fastr = [];
fastr.name = "FASTR";
fastr.options.slack = 5e-3;
fastr.options.nrSegsPerWindow = 10;
fastr.options.pcaNr = 2;
fastr.options.pcaVarExplained = Inf;
fastr.options.pcaNrSegsPerWindow = Inf;
fastr.options.referenceSegment = 1;

fbar= [];
fbar.name = "FBAR";
fbar.options.frequencyLimits = [-1 1];

rbar = [];
rbar.name = "RBAR";
rbar.options = [];
%%
%[text] %[text:anchor:H_DDD99D7B] ## Recovering neural signals and background
%[text] Create the artSim object using the default parameters defined above.
A = artSim(defaults);
A.sim;
%[text] Now A.vContaminated has the simulated time series. Generate a figure, run artifact removal, and show coarse (1 Hz) spectral results.
%%
[~,axs4] = fig('Name','Fig2','paperCols',2,'height',10,'nrRows',3,'nrCols',4,'byColumn',true,dx=4); %[output:4e98bb8d]
frequencyResolution = 1;
%[text] %[text:anchor:H_218F3721] ### FASTR
%[text] Template based artifact removal 
[arResultsFastr] = artifactRemoval(A.vContaminated,fastr,arArgs{:},groundTruth  =A.vTruth); %[output:8f864f70]
analyzeEEG(A,arResultsFastr,freqRes=frequencyResolution,axs=axs4(1,1:3),legend=false); %[output:4e98bb8d]
%[text] ### FBAR
%[text] Fourier based artifact removal
arResultsFbar = artifactRemoval(A.vContaminated,fbar,arArgs{:},groundTruth  =A.vTruth); %[output:9c494a5d]
analyzeEEG(A,arResultsFbar,freqRes=frequencyResolution,axs=axs4(2,1:3),legend=false); %[output:4e98bb8d]
%[text] %[text:anchor:H_AAE631F7] ### RBAR
%[text] Regression based artifact removal:
arResultsRbar= artifactRemoval(A.vContaminated,rbar,arArgs{:},vRecordTcs = A.vRecordTcs,groundTruth  =A.vTruth); %[output:6aa701bb]
analyzeEEG(A,arResultsRbar,freqRes=frequencyResolution,axs=axs4(3,1:3),legend=false); %[output:4e98bb8d]
%[text] 
frequencyResolution = 0.1;
resultsFastr = analyzeEEG(A,arResultsFastr,forbidden = A.tacsFrequency + [-2 2],freqRes=frequencyResolution,axs=[gobjects(1,2) axs4(1,4)],legend=false); %[output:4e98bb8d]
resultsFbar = analyzeEEG(A,arResultsFbar,forbidden = A.tacsFrequency + [-2 2],freqRes=frequencyResolution,axs=[gobjects(1,2) axs4(2,4)],legend=false); %[output:4e98bb8d]
resultsRbar = analyzeEEG(A,arResultsRbar,forbidden = A.tacsFrequency + [-2 2],freqRes=frequencyResolution,axs=[gobjects(1,2) axs4(3,4)],legend=false); %[output:4e98bb8d]
ylim(axs4(:,[3 4]),[-40 40]) %[output:4e98bb8d]
fprintf('FASTR: r_t = %.2f , re = %.2f%%n',arResultsFastr.r.FASTR, resultsFastr.relativeError) %[output:22db4bb2]
fprintf('FBAR: r_t = %.2f , re = %.2f%%n',arResultsFbar.r.FBAR, resultsFbar.relativeError) %[output:7ddcbf4a]
fprintf('RBAR: r_t = %.2f , re = %.2f%%n',arResultsRbar.r.RBAR, resultsRbar.relativeError) %[output:6c2e6b0b]
%[text] The first columnshows a 100 ms snippet of the simulated neural signals (red) and recovered signal (green) on the left axis. The artfiact (blue) is orders of magnitude larger and shown on the right axis. Some mismatches between ground truth and recovered signals are visible in these snippets. 
%[text] The mismatch is easier to see in the spectral domain (second column); mismatches are biggest near the tACS frequency, but also spread across the specrum.  The third column expresses the mismatch as a percentage of ground truth signal; FASTR has residual errors across the spectrum, FBAR & RBAR perform better, recovering most of the spectrum, except for a band around the tACS frequency ("forbidden band").
%[text] The peak in the FBAR error spectrum at 30 Hz is a consequence of the discretization of the stimulation current; this creates an artifact at the (odd) harmonics of the 10Hz tACS frequency, which FBAR does not remove becuase it only removes the fundamental. While this could be addressed by removing harmonics of the tACS frequency as well, that would come at the cost of additional forbidden zones.
%[text] The fourth column illustrates that relatively minor changes in the analysis pipeline can result in qualitatively different interpretations of the results. The only difference was a change in the frequency resolution of the display (no change in the artifact removal algorithms). This high resolution analysis reveals persistent errors in FASTR and, to a somewhat lesser extent, in FBAR,
%%
%[text] Quantify the residual errors in the estimation of the power of the intrinsic neural oscillation. This depends on the size of the artifact, which I vary here by varying the resistance between a very low value (representative for an electrode far away from the stimulation electrodfe) to ~100 for  a nearby electrode (resulting in a 100 mV artifact).

frequencyResolution = 0.1;
arModes = {fastr,fbar,rbar};
resistances = [ 15 30 60 120 240 480];
nrModes=  numel(arModes);
nrResistances = numel(resistances);
re = nan(nrResistances,nrModes);
fBand = nan(nrResistances,nrModes);
rt = nan(nrResistances,nrModes);
for m = 1:nrModes
    for r = 1:nrResistances
        A = artSim(defaults);
        A.resistance = resistances(r);        
        A.adcNonlinearity = 4;
        A.sim;
        tmpArResult = artifactRemoval(A.vContaminated,arModes{m},arArgs{:},vRecordTcs =A.vRecordTcs,groundTruth = A.vTruth);
        tmpR = analyzeEEG(A,tmpArResult,forbidden = A.tacsFrequency + [-2 2], freqRes=frequencyResolution,axs=[]);
        re(r,m) =tmpR.relativeError;
        fBand(r,m) = tmpR.forbidden;
        rt(r,m) = tmpArResult.r.(upper(arModes{m}.name));
    end
end
figure;
yyaxis left
plot(resistances,re)
legend (cellfun(@(x) (x.name),arModes))
ylabel 're (%)'
yyaxis right
plot(resistances,rt)
xlabel 'Resistance (\Omega)'
ylabel 'r_t'
legend (cellfun(@(x) (x.name),arModes))


%%
%[text] RBAR should outperform the other approaches because by measuring the applied voltage, it has access to more information. Noise in this measured artifact proxy, however, could affect the outcome negatively. The `additiveTcs` parameter controls this additive measurement noise. 
frequencyResolution = 0.1;
proxyNoises =  2.^(0:5)*1e-6;
nrNoiseLevels = numel(proxyNoises);
reProxy = nan(nrNoiseLevels,1);
for p =1:nrNoiseLevels
    A = artSim(defaults);
    A.additiveTcs = proxyNoises(p);
    A.sim;
    tmpArResult = artifactRemoval(A.vContaminated,rbar,arArgs{:},vRecordTcs =A.vRecordTcs);
    tmpR = analyzeEEG(A,tmpArResult,forbidden = A.tacsFrequency + [-2 2], freqRes=frequencyResolution,axs=[]);
    reProxy(p)=tmpR.relativeError;
end
clf
plot(proxyNoises/1e-6,reProxy);
ylabel 're (%)'
title 'Relative Error vs Proxy Noise'
%[text] This plot shows that for a wide range of noise levels (that should be obtainable in a well-designed measurement of the stimulation proxy), the relative error remains small.
%%
%[text] %[text:anchor:H_370D044C] ## Impedance Artifacts tACS
%[text] Physiological artifacts such as heartbeats, sweating, or breathing change impedance and interact multiplicatively with the signal. FASTR has a hard time recovering any underlying signals.
%[text] Keeping the neural signals from above, but adding an artifact that rhytmically (`o.zFrequency`) changes the impedance sinusoidally (maybe a reasonable approximation for respiration not so much for a heartbeat), The maximum change in the impedance is defined (as a fraction) by `o.zAmplitude.`
A            = artSim(defaults); % Start fresh
A.zFrequency = 18/60;  % 18 breaths per minute
A.zAmplitude = 0.05;  % The artifact changes the impedance by 5%.

%[text] Run the simulation
A.sim;
[~,axs] = fig('Name','Fig3','paperCols',2,'height',12,'nrRows',4,'nrCols',2,'byColumn',true,'span',{[1 1 2],[3 1 1],[4 1 1],[5 1 2], [7 1 1],[8 1 1]},'dx',4); %[output:95b14795]

frequencyResolution = 0.1;
tlim = [0 1./A.zFrequency] + mean(A.tRecord);
arResultsFastr = artifactRemoval(A.vContaminated,fastr,arArgs{:},groundTruth = A.vTruth); %[output:9a0a7a7b]
resultsFastr = analyzeEEG(A,arResultsFastr,tlim=tlim,forbidden= A.tacsFrequency + [-2 2],freqRes=frequencyResolution,axs=[axs(1:3)],legend=false); %[output:95b14795]
axes(axs(1)); %[output:95b14795]
yyaxis right; 
hold on; %[output:95b14795]
stay = A.tSimulate >= tlim(1)  & A.tSimulate <= tlim(2);  
z = A.z(stay)- mean(A.z);
scale = 0.5*max(ylim)/max(z); 
z = z.*scale;
plot(A.tSimulate(stay)-tlim(1),z,'c-','LineWidth',1) %[output:95b14795]
arResultsRbar= artifactRemoval(A.vContaminated,rbar,arArgs{:},vRecordTcs = A.vRecordTcs,groundTruth =A.vTruth); %[output:950d0fb5]
resultsRbar = analyzeEEG(A,arResultsRbar,tlim=tlim,forbidden= A.tacsFrequency + [-2 2],freqRes=frequencyResolution,axs=[axs(4:6)],legend=false); %[output:95b14795]
plot(axs(4),A.tSimulate(stay)-tlim(1),z,'c-','LineWidth',1) %[output:95b14795]
ylim(axs(3),[-100 100]) %[output:95b14795]

fprintf('FASTR: r_t = %.2f , re = %.2f%%n',arResultsFastr.r.FASTR, resultsFastr.relativeError) %[output:6222e36c]
fprintf('RBAR: r_t = %.2f , re = %.2f%%n',arResultsRbar.r.RBAR, resultsRbar.relativeError) %[output:206ded88]
%%
%[text] Next we simulate a impedance modulation that models the ballistic artifacts expected from a heartbeat. This uses an ECG recording and a simple body resonance model to simulate the ballistic impedance changes. See `zHeartbeat.m` for details.
[~,axs] = fig('Name','Fig4','paperCols',2,'height',12,'nrRows',4,'nrCols',2,'byColumn',true,'span',{[1 1 2],[3 1 1],[4 1 1],[5 1 2], [7 1 1],[8 1 1]},'dx',4); %[output:2d5ca91c]
A.zFun = @zHeartbeat ;
A.sim;

tlim = [0 3] + mean(A.tRecord);
arResultsFastr = artifactRemoval(A.vContaminated,fastr,arArgs{:},groundTruth = A.vTruth); %[output:59621185]
resultsFastr = analyzeEEG(A,arResultsFastr,tlim=tlim,forbidden= A.tacsFrequency + [-2 2],freqRes=frequencyResolution,axs=axs(1:3),legend=false); %[output:2d5ca91c]
axes(axs(1)); %[output:2d5ca91c]
yyaxis right; 
hold on; %[output:2d5ca91c]
stay = A.tSimulate >= tlim(1)  & A.tSimulate <= tlim(2);  
z = A.z(stay)- mean(A.z);
scale = 0.5*max(ylim)/max(z);
z = z.*scale;
plot(A.tSimulate(stay)-tlim(1),z,'c-','LineWidth',1) %[output:2d5ca91c]

arResultsRbar= artifactRemoval(A.vContaminated,rbar,arArgs{:},vRecordTcs = A.vRecordTcs,groundTruth = A.vTruth); %[output:8093b051]
resultsRbar = analyzeEEG(A,arResultsRbar,tlim=tlim,forbidden= A.tacsFrequency + [-2 2],freqRes=frequencyResolution,axs=axs(4:6),legend=false); %[output:2d5ca91c]
%ylim(axs,[-40 40])
plot(axs(4),A.tSimulate(stay)-tlim(1),z,'c-','LineWidth',1) %[output:2d5ca91c]

fprintf('FASTR: r_t = %.2f , re = %.2f%%n',arResultsFastr.r.FASTR, resultsFastr.relativeError) %[output:6fb4ea0c]
fprintf('RBAR: r_t = %.2f , re = %.2f%%n',arResultsRbar.r.RBAR, resultsRbar.relativeError) %[output:0fc8a6c3]
%[text] 
%[text] Clearly FASTR (a,c) does not recover the neural signal of either sinusoidal/breathing (a) or pulsed/heartbeat (b) impedance artifacts; the multiplicative interactions between physiological artifacts and the true neural signal results in spurious signals across the entire spectrum.  Noury et al explain why this should happen and why there are two prominent peaks in a).  RBAR gets rid of most artifacts and only has a small forbidden zone near the tACS frequency. FBAR (not shown) has the same kind of issues as FASTR.
%[text] 
%%
%[text] ## Imedance Artifacts tDCS
%[text] As long as recordings exclude the ramp up and ramp down periods, the DC current generated by tDCS does not introduce neural artifacts on its own (although the presence of the device near the recording could introduce additional noise).  
%[text] However, impedance artifacts induced by physiological changes such as heartbeats can result in spurious neural signals. 
A                           = artSim(defaults);      % Start fresh
A.tdcsMean                  = 1e-3;         % Add DC
A.tacsAmplitude             = 0;            % Turn off AC
A.zFun  =  @zHeartbeat;
A.zAmplitude = 0.05;  % The artifact changes the impedance by 5%.
A.sim;
%[text] Create a copy artSim object to simulate without noise and neural signal. (Only used to get the pure artifact spectrum)
N =copy(A); 
N.additive = 0;
N.lfpFrequency = 0;
N.sim;

arDC = rmfield(ar,'tacsFrequency');
arDC.segmentDuration = 24;
arDC =namedargs2cell(arDC);
frequencyResolution = .5;
%%

[~,axs] = fig('Name','Fig5','paperCols',1.5,'height',9,'nrRows',2,'nrCols',3,span={[1 1 2],[3 1 1],[4 1 2],[6 1 1]}); %[output:48cdbf1f]
%[text] Zoom in on the timecourse near a heartbeat to illustrate the effect. 
tlim = [0.3 0.8];

arResultsRbar = artifactRemoval(A.vContaminated,rbar,arDC{:},vRecordTcs = A.vRecordTcs);
resultsRbar = analyzeEEG(A,arResultsRbar,showErrorMuv= true,tlim=tlim,freqRes=frequencyResolution,axs=[axs(1) axs(3) axs(4)],legend=false); %[output:48cdbf1f]
%[text] Show the error spectrum without artifact correction ("nop") and without noise to isolate the errors from the CBA.

arResultsNop = artifactRemoval(N.vContaminated,struct('name','nop'),arDC{:});
analyzeEEG(N,arResultsNop,showErrorMuv= true,tlim=tlim,freqRes=frequencyResolution,axs=[gobjects(1,2) axs(2)],legend=false); %[output:48cdbf1f]
%[text] 
% Mark the I J K waves of the CBA
yyaxis(axs(1),'left') %[output:48cdbf1f]
set(axs(1),'XTick',0:0.1:0.5); %[output:48cdbf1f]
text(axs(1),0.085,-150,'I'); %[output:48cdbf1f]
text(axs(1),0.15,210,'J'); %[output:48cdbf1f]
text(axs(1),0.25,-150,'K'); %[output:48cdbf1f]
line(axs(1),[0.05 0.32],[190 190],'LineStyle','-','Color','k') %[output:48cdbf1f]
yyaxis(axs(2),'left'); %[output:48cdbf1f]
delete(axs(2).Children) % percent error is too large to show (small neural signal) %[output:48cdbf1f]
set(axs(2),'YTick',[]); %[output:48cdbf1f]
ylabel(axs(2),''); %[output:48cdbf1f]
yyaxis(axs(2),'right'); %[output:48cdbf1f]
ylim(axs(2),[0 100]); %[output:48cdbf1f]
yyaxis(axs(4),'right');
ylim(axs(4),[-0.2 2]); %[output:48cdbf1f]
yyaxis(axs(4),'left'); %[output:48cdbf1f]
ylim(axs(4),[-1 10]); %[output:48cdbf1f]
axes(axs(1)); %[output:48cdbf1f]


